-- 004: logo dan catatan kaki faktur per perusahaan.
-- Jalankan sekali di Supabase SQL Editor, setelah 001-003.

alter table perusahaan add column if not exists logo text;            -- gambar sebagai data URL (PNG/JPG kecil)
alter table perusahaan add column if not exists catatan_faktur text;  -- teks "Perhatian" di bawah faktur penjualan

update perusahaan set
  catatan_faktur = 'APABILA PENGGANTIAN BENIH DILAKUKAN DALAM 3 BULAN SEBELUM TANGGAL KADALUARSA, MAKA AKAN DIKENAKAN POTONGAN 50%.' || chr(10) ||
                   'MOHON BARANG DITERIMA DENGAN BAIK DAN DIPERIKSA. HANYA MENERIMA KOMPLAIN MAX 10 HARI SETELAH BARANG DITERIMA.',
  logo = 'data:image/png;base64,'
where kode = 'PAP' and catatan_faktur is null;
